-- Community shops & products (27 Oct 2026).
-- Replaces the placeholder shops from the demo seed with products documented in the
-- research (subdistrict motto, Cultural Mapping Thailand TC-44110-00005, FF proposal).
-- The last 3 rows are new business ideas, kept unpublished until the community approves.
-- Producer names, phones and coordinates are added later via the admin UI, with consent.
-- Safe on any database: only removes placeholders that never got a contact, and skips
-- rows whose Thai name already exists.

DELETE FROM shops
WHERE contact = ''
  AND name->>'th' IN ('ผ้าไหมมัดหมี่เมืองเตา','หมวกจักสาน','ข้าวหอมมะลิ 105 ทุ่งกุลา','สมุนไพรพื้นบ้าน',
                      'กลุ่มทอผ้าบ้านเมืองเตา (ตัวอย่าง)','ครัวอีสานบ้านเมืองเตา (ตัวอย่าง)');

INSERT INTO shops(name, kind, products, description, images, published)
SELECT v.name::jsonb, v.kind, v.products::jsonb, v.description::jsonb, v.images, v.published
FROM (VALUES
(1, '{"th": "ผ้าไหมมัดหมี่เมืองเตา", "zh": "孟涛扎染丝绸", "en": "Mueang Tao mudmee silk"}','product','{"th": "ผ้าไหมมัดหมี่ทอมือ ผ้าซิ่น ผ้าพันคอ", "zh": "手工扎染丝绸、筒裙布、围巾", "en": "Hand-woven mudmee silk, sarong lengths, scarves"}','{"th": "“งามวิไลไหมมัดหมี่” ของดีตามคำขวัญตำบลเมืองเตา ชาวบ้านทอผ้าเพื่อสืบทอดภูมิปัญญาและสร้างรายได้ ซื้อเป็นของฝากหรือสวมใส่มาไหว้เจ้าพ่อได้ (กำลังรวบรวมรายชื่อผู้ทอและช่องทางสั่งซื้อจากชุมชน)", "zh": "孟涛乡标语中的“扎染丝绸秀丽”。村民织布以传承技艺、增加收入，可作伴手礼，也可穿着前来参拜。（织户名单与购买方式正在向社区收集）", "en": "“Lovely mudmee silk” from the subdistrict motto. Villagers weave to keep the craft alive and earn income — a gift to take home, or something to wear when you visit the shrine. (Weaver list and ordering details are being collected from the community.)"}',ARRAY['https://images.unsplash.com/photo-1569909115134-a0426936c879?auto=format&fit=crop&w=1200&q=75'],true),
(2, '{"th": "หมวกจักสานเมืองเตา", "zh": "孟涛编织帽", "en": "Mueang Tao woven hats"}','product','{"th": "หมวกจักสานและงานจักสานขนาดเล็ก", "zh": "编织帽与小件编织品", "en": "Woven hats and small woven goods"}','{"th": "“รู้กันดีหมวกจักสาน” งานฝีมือที่ขึ้นชื่อของตำบลเมืองเตา ใช้กันแดดในทุ่งนาได้จริง และเป็นของฝากน้ำหนักเบา (กำลังรวบรวมรายชื่อผู้ผลิตจากชุมชน)", "zh": "孟涛乡标语中的“编织帽远近闻名”，可在田间遮阳，也是轻便的伴手礼。（生产者名单正在收集）", "en": "“Well-known woven hats” from the subdistrict motto — practical shade in the rice fields and a light souvenir. (Producer list is being collected.)"}',ARRAY['https://images.unsplash.com/photo-1747396108528-682b02327818?auto=format&fit=crop&w=1200&q=75'],true),
(3, '{"th": "เครื่องจักสานไม้ไผ่บ้านเมืองเตา", "zh": "孟涛竹编器具", "en": "Ban Mueang Tao bamboo basketry"}','product','{"th": "หวดนึ่งข้าวเหนียว กระติบข้าว ไซดักปลา", "zh": "糯米蒸笼、糯米饭盒、捕鱼篓", "en": "Sticky-rice steamers, rice baskets, fish traps"}','{"th": "ภูมิปัญญาจักสานไม้ไผ่ที่ใช้ในวิถีชีวิตชาวนาทุ่งกุลา ปัจจุบันเหลือผู้สืบทอดน้อยและรับทำตามสั่ง การซื้อช่วยให้ภูมิปัญญานี้อยู่ต่อ (กำลังประสานผู้ทำและช่องทางสั่งทำ)", "zh": "图拉平原稻农生活中使用的竹编技艺，如今传承人很少，按订单制作。购买有助于延续这门手艺。（正在联系制作者与订购方式）", "en": "Bamboo craft from Thung Kula farming life. Few makers remain and pieces are made to order — buying one helps keep the skill alive. (Maker and ordering details are being arranged.)"}','{}'::text[],true),
(4, '{"th": "ข้าวหอมมะลิ 105 ทุ่งกุลาร้องไห้", "zh": "古拉龙海平原茉莉香米105", "en": "Thung Kula Rong Hai Hom Mali 105 rice"}','product','{"th": "ข้าวหอมมะลิ 105 ข้าวสาร บรรจุถุงของฝาก", "zh": "茉莉香米105（袋装伴手礼）", "en": "Hom Mali 105 jasmine rice, gift bags"}','{"th": "“ถิ่นข้าวหอมมะลิหนึ่งศูนย์ห้า” ข้าวจากนาในทุ่งกุลาร้องไห้ อาชีพหลักของชาวบ้านเมืองเตา ข้าวหอมมะลิทุ่งกุลาร้องไห้ได้ขึ้นทะเบียนสิ่งบ่งชี้ทางภูมิศาสตร์ (GI) (กำลังรวบรวมรายชื่อผู้จำหน่ายจากชุมชน)", "zh": "孟涛乡标语中的“茉莉香米105之乡”，产自古拉龙海平原稻田，是村民的主要生计。古拉龙海茉莉香米已注册地理标志（GI）。（销售者名单正在收集）", "en": "“Home of Hom Mali 105”, grown in the Thung Kula Rong Hai fields that are the village''s main livelihood. Thung Kula Rong Hai Hom Mali rice is a registered Geographical Indication (GI). (Seller list is being collected.)"}',ARRAY['https://images.unsplash.com/photo-1647167363124-d3567bdcb7df?auto=format&fit=crop&w=1200&q=75'],true),
(5, '{"th": "สมุนไพรพื้นบ้านเมืองเตา", "zh": "孟涛民间草药", "en": "Mueang Tao folk herbs"}','product','{"th": "สมุนไพรแห้ง ยาหม่อง ลูกประคบ (ตามที่ชุมชนผลิต)", "zh": "干草药、药膏、药草热敷包（视社区生产而定）", "en": "Dried herbs, balms, herbal compresses (as produced locally)"}','{"th": "“สมุนไพรเลื่องลือ” ชาวบ้านเมืองเตาใช้สมุนไพรดูแลสุขภาพควบคู่กับการแพทย์สมัยใหม่ (กำลังรวบรวมผู้ผลิตและผลิตภัณฑ์ที่มีจำหน่ายจริง)", "zh": "孟涛乡标语中的“草药声名远扬”。村民将草药与现代医学结合使用。（正在收集生产者与实际在售产品）", "en": "“Famed herbs” from the subdistrict motto; villagers use them alongside modern medicine. (Producers and products actually on sale are being collected.)"}','{}'::text[],true),
(6, '{"th": "อาหารพื้นบ้านอีสานเมืองเตา", "zh": "孟涛东北家常菜", "en": "Mueang Tao Isan home cooking"}','food','{"th": "อาหารอีสานพื้นบ้านจากวัตถุดิบในชุมชน", "zh": "以社区食材制作的东北家常菜", "en": "Isan dishes made from village produce"}','{"th": "อาหารพื้นเมืองที่ชาวบ้านทำกินในวิถีทุ่งกุลา แวะชิมได้หลังสักการะ (กำลังรวบรวมรายชื่อร้านอาหารและเวลาเปิดจากชุมชน)", "zh": "图拉平原村民日常的家常菜，参拜后可顺道品尝。（餐馆名单与营业时间正在收集）", "en": "Everyday village food of the Thung Kula plain — stop for a meal after visiting the shrine. (Restaurant list and opening hours are being collected.)"}','{}'::text[],true),
(7, '{"th": "ชุดเครื่องสักการะเจ้าพ่อศรีนครเตา", "zh": "四那空涛神供品套装", "en": "Chao Pho Si Nakhon Tao offering sets"}','shop','{"th": "ดอกไม้ ธูป เทียน จัดชุดตามแบบที่ชุมชนกำหนด", "zh": "按社区规定配好的鲜花、香、蜡烛", "en": "Flowers, incense and candles, set out the way the community prescribes"}','{"th": "ชุดเครื่องสักการะจัดโดยครัวเรือนในชุมชน จำหน่ายหน้าศาล นักท่องเที่ยวไม่ต้องเตรียมมาเอง และรายได้อยู่ในชุมชน", "zh": "由社区家庭配好的供品套装，在神祠前出售，游客无需自备，收入留在社区。", "en": "Offering sets made up by village households and sold at the shrine, so visitors need not bring their own and the income stays local."}','{}'::text[],false),
(8, '{"th": "กิจกรรมเรียนรู้ ทอผ้าและจักสานกับปราชญ์ชุมชน", "zh": "跟社区匠人学织布与竹编", "en": "Weaving and basketry with village masters"}','shop','{"th": "กิจกรรมครึ่งวัน ทดลองทอผ้า สานไม้ไผ่ และทำอาหารพื้นบ้าน", "zh": "半日体验：织布、竹编、做家常菜", "en": "Half-day sessions: weaving, bamboo craft, local cooking"}','{"th": "ประสบการณ์ท่องเที่ยวที่เพิ่มรายได้ให้ผู้ทอและผู้สานโดยตรง จองล่วงหน้าผ่านผู้ประสานงานชุมชน", "zh": "直接为织工与竹编匠人增加收入的体验活动，需通过社区联络人提前预约。", "en": "A hands-on visit that pays weavers and basket-makers directly. Book ahead through the community coordinator."}','{}'::text[],false),
(9, '{"th": "โฮมสเตย์บ้านเมืองเตา", "zh": "孟涛村民宿", "en": "Ban Mueang Tao homestay"}','stay','{"th": "ที่พักในบ้านชาวบ้าน พร้อมอาหารเช้าพื้นบ้าน", "zh": "住在村民家中，含家常早餐", "en": "Rooms in village homes with a local breakfast"}','{"th": "สำหรับผู้มาร่วมงานเดือน 4 หรือพิธีขอฝน ซึ่งต้องค้างคืน", "zh": "适合前来参加四月庆典或祈雨仪式、需要留宿的游客。", "en": "For visitors coming to the fourth-month festival or the rain ceremony who need to stay overnight."}','{}'::text[],false)
) AS v(ord, name, kind, products, description, images, published)
WHERE NOT EXISTS (SELECT 1 FROM shops s WHERE s.name->>'th' = v.name::jsonb->>'th')
ORDER BY v.ord;
